{
  "sop_id": "SOP-013",
  "title": "Bill of Quantities (BOQ) Review",
  "steps": [
    {
      "step_id": "S1",
      "name": "Create ticket and assign",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Check completeness (template checklist)",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Verify quantities and rates",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Summarise variance, list non-standard items, submit",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "D1",
      "name": "Wait for drawings/take-off confirmation (Dependency)",
      "role": "System",
      "type": "rework"
    },
    {
      "step_id": "A1",
      "name": "Incharge approval or rejection",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "R1",
      "name": "Rework on rejection (max 2 attempts, then Lead escalation)",
      "role": "Executor",
      "type": "rework"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "exceptions (EX-HIGHVAL, EX-NEWITEM)"
    }
  ],
  "dependencies": [
    {
      "dep_id": "D1",
      "provider": "Operations",
      "item": "Drawings and take-off confirmation",
      "parallel_group": null
    }
  ],
  "rework_reasons": [
    "Wrong quantity",
    "Amount mismatch",
    "Incorrect category",
    "Required document missing"
  ],
  "first_pass_yield_target": 0.9
}
